    address public MCISoftwareWallet = 0x81208B498Dff72A239762C4B103b54b6B178Ee40;

    uint256 public _MarketingFee = 2;
    address public MarketingWallet = 0x2732d866BB7BaB3D3C6fffD7DA24697E8e15af6a;

    uint256 private _previousMarketingFee = _MarketingFee;
    uint256 private _previousMCISoftwareFee = _MCISoftwareFee;


