library Arrays {

    function findDownerBound(uint256[] storage array, uint256 element)

        internal

        view

        returns (uint256)

    {

        if (array.length == 0) {

            return 0;

        }

        uint256 low = 0;

        uint256 high = array.length - 1;

        while (low <= high) {

            uint256 mid = (low + high) / 2;

            if (array[mid] == element) {

                return mid;

            } else if (array[mid] > element) {

                if (mid == 0) {

                    return 0;

                } else {

                    high = mid - 1;

                }

            } else {

                low = mid + 1;

            }

        }

        return low == 0 ? low : low - 1;

    }

