                                TBG_2BNB = 80;



                            } else if (GEN.balanceOf(Wallet_TBG_AFF) >= Tier_2){



                                AFF_2BNB = 15;

                                TBG_2BNB = 85;



                            } else {



                                AFF_2BNB = 10;

                                TBG_2BNB = 90;



                            }



