    function swapBack() internal swapping {



        uint256 totalETHFee = totalFee;



        uint256 amountToLiquify = (swapThreshold * liquidityFee)/(totalETHFee * 2);

        uint256 amountToSwap = swapThreshold - amountToLiquify;



