        setSwapAndLiquifyEnabled(true);
        _isExcludedFromFee[deadAddress] = true;
        _taxFee = 10;
        _liquidityFee = 2;
        buyLimit = _tTotal.div(100);
        sellLimit= _tTotal.div(100);
