    function _checkBuySellLimits(address from, address to, uint256 amount) private {
        if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) return;
        require(presaleMode || isLive, "Contract is not live");
        currentWalleTaxFee = 0;

