        minimumTokensBeforeSwap = totalSupply_.mul(2).div(10**6) * 10**_decimals; 

        marketingWalletAddress= payable(0x5BA470C4D72DCf61d2829b6DbB9F2F9A3398ed8E);

        teamWalletAddress= payable(0x8289CD0374162Ee3E27477e90Bf30A4cEaBB3cbd );

        //IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0xB6BA90af76D139AB3170c7df0139636dB6120F7e); 

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E); 

        //0x10ED43C718714eb63d5aA57B78B54704E256024E

        uniswapPair = IUniswapV2Factory(_uniswapV2Router.factory())

            .createPair(address(this), _uniswapV2Router.WETH());



