contract AlphaProtocol is ERC20Detailed, Ownable {



    using SafeMath for uint256;

    using SafeMathInt for int256;



    event LogRebase(uint256 indexed epoch, uint256 totalSupply);



    IPancakeSwapPair public pairContract;

    mapping(address => bool) _isFeeExempt;



    modifier validRecipient(address to) {

        require(to != address(0x0));

        _;

    }



    uint256 public constant DECIMALS = 5;

    uint256 public constant MAX_UINT256 = ~uint256(0);

    uint8 public constant RATE_DECIMALS = 11;



    uint256 private constant INITIAL_FRAGMENTS_SUPPLY =

        1000 * 10**3 * 10**DECIMALS;



    uint256 public liquidityFee = 30;

    uint256 public treasuryFee = 50;

    uint256 public safuDividendFee = 10;

    uint256 public sellFee = 20;

    uint256 public autofirePitFee = 10;

    uint256 public totalFee =

        liquidityFee.add(treasuryFee).add(safuDividendFee).add(

            autofirePitFee

        );

    uint256 public feeDenominator = 1000;



    address DEAD = 0x000000000000000000000000000000000000dEaD;

    address ZERO = 0x0000000000000000000000000000000000000000;



    address public autoLiquidityReceiver;

    address public treasuryReceiver;



    DividendDistributor distributor;

    address public safuDividendReceiver;

    uint256 distributorGas = 500000;



    address public autofirePit;

    bool public swapEnabled = true;

    IPancakeSwapRouter public router;

    uint256 public TwentyFourHours = 24 hours;



    // Anti Dump Mech

    struct SellHistory {

        uint256 timestamp;

        uint256 amount;

    }

    uint256 public maxSellPerDay = 7000; // 100 = 1%

    mapping(address => SellHistory) public lastSell;



    uint256 public transferTax = 5000; // 100 = 1%



    address public pair;

    bool inSwap = false;

    modifier swapping() {

        inSwap = true;

        _;

        inSwap = false;

    }



    uint256 private constant TOTAL_GONS =

        MAX_UINT256 - (MAX_UINT256 % INITIAL_FRAGMENTS_SUPPLY);



    uint256 private constant MAX_SUPPLY = 1000 * 10**11 * 10**DECIMALS;



    bool public _autoRebase;

    bool public _autoAddLiquidity;

    uint256 public _initRebaseStartTime;

    uint256 public _lastRebasedTime;

    uint256 public _lastAddLiquidityTime;

    uint256 public _totalSupply;

    uint256 private _gonsPerFragment;



    mapping(address => uint256) private _gonBalances;

    mapping(address => mapping(address => uint256)) private _allowedFragments;

    mapping(address => bool) public blacklist;

    mapping(address => bool) public isDividendExempt;



    constructor() ERC20Detailed("AlphaProtocol", "AlphaPro", uint8(DECIMALS)) Ownable() {



        //testnet

        // router = IPancakeSwapRouter(0x9Ac64Cc6e4415144C455BD8E4837Fea55603e5c3); 



        //mainnet

        router = IPancakeSwapRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E); 

        pair = IPancakeSwapFactory(router.factory()).createPair(

            router.WETH(),

            address(this)

        );



        autoLiquidityReceiver = 0x84137e20048329f27E67b3Df996a9Af893fF6224;

        treasuryReceiver = 0x7c1a586f27423d021DF0cCbE306Db5f222fff55e;   

        autofirePit = 0x000000000000000000000000000000000000dEaD;



        _allowedFragments[address(this)][address(router)] = uint256(-1);

        pairContract = IPancakeSwapPair(pair);



        distributor = new DividendDistributor(address(router));

        safuDividendReceiver = address(distributor);



        isDividendExempt[msg.sender] = true;

        isDividendExempt[pair] = true;

        isDividendExempt[address(this)] = true;

        isDividendExempt[DEAD] = true;



        _totalSupply = INITIAL_FRAGMENTS_SUPPLY;

        _gonBalances[treasuryReceiver] = TOTAL_GONS;

        _gonsPerFragment = TOTAL_GONS.div(_totalSupply);

        _initRebaseStartTime = block.timestamp;

        _lastRebasedTime = block.timestamp;

        _autoRebase = false;

        _autoAddLiquidity = true;

        _isFeeExempt[treasuryReceiver] = true;

        _isFeeExempt[address(this)] = true;



        _transferOwnership(treasuryReceiver);

        emit Transfer(address(0x0), treasuryReceiver, _totalSupply);

    }



    function rebase() internal {



        if ( inSwap ) return;

        uint256 rebaseRate;

        uint256 deltaTimeFromInit = block.timestamp - _initRebaseStartTime;

        uint256 deltaTime = block.timestamp - _lastRebasedTime;

        uint256 times = deltaTime.div(30 minutes);

        uint256 epoch = times.mul(30);

        if (deltaTimeFromInit <= (365 days)) {

            rebaseRate = 19435595;

        } else if (deltaTimeFromInit >= (365 days)) {

            rebaseRate = 9717797;

        } else if (deltaTimeFromInit >= ((15 * 365 days) / 10)) {

            rebaseRate = 2858898;

        } else if (deltaTimeFromInit >= (7 * 365 days)) {

            rebaseRate = 1929449;

        }



        for (uint256 i = 0; i < times; i++) {

            _totalSupply = _totalSupply

                .mul((10**RATE_DECIMALS).add(rebaseRate))

                .div(10**RATE_DECIMALS);

        }



        _gonsPerFragment = TOTAL_GONS.div(_totalSupply);

        _lastRebasedTime = _lastRebasedTime.add(times.mul(30 minutes));



        pairContract.sync();



        emit LogRebase(epoch, _totalSupply);

    }



    function transfer(address to, uint256 value)

        external

        override

        validRecipient(to)

        returns (bool)

    {

        _transferFrom(msg.sender, to, value);

        return true;

    }



    function transferFrom(

        address from,

        address to,

        uint256 value

    ) external override validRecipient(to) returns (bool) {



        if (_allowedFragments[from][msg.sender] != uint256(-1)) {

            _allowedFragments[from][msg.sender] = _allowedFragments[from][

                msg.sender

            ].sub(value, "Insufficient Allowance");

        }

        _transferFrom(from, to, value);

        return true;

    }

    function _basicTransfer(

        address from,

        address to,

        uint256 amount

    ) internal returns (bool) {

        uint256 gonAmount = amount.mul(_gonsPerFragment);

        _gonBalances[from] = _gonBalances[from].sub(gonAmount);

        _gonBalances[to] = _gonBalances[to].add(gonAmount);

        return true;

    }

    function checkLimit(address sender,

        address recipient,

        uint256 amount) internal {

        if (recipient == pair && !_isFeeExempt[sender]) {

            uint256 limitSell = balanceOf(sender).mul(maxSellPerDay).div(10000);

            require(amount <= limitSell,  "Alpha Protocol: Cant Sell More Than Allowed Per Day");

            if (block.timestamp > lastSell[sender].timestamp + TwentyFourHours) {

                lastSell[sender].timestamp = block.timestamp;

                lastSell[sender].amount = amount;

            } else if ((block.timestamp < lastSell[sender].timestamp  + TwentyFourHours) && (block.timestamp > lastSell[sender].timestamp)) {

                require(lastSell[sender].amount + amount <= limitSell,  "Alpha Protocol: Cant Sell More Than Allowed Per Day");

                lastSell[sender].amount = lastSell[sender].amount +  amount;



            }

        }

    }

    function taxTransfer(address sender,

        address recipient,

        uint256 amount) internal returns (uint256) {

        if(transferTax > 0 && !_isFeeExempt[sender]) {

            if(!isContract(sender) && !isContract(recipient)) {

                uint256 taxAmount = amount.mul(transferTax).div(10000);

                amount  = amount - taxAmount;

                _basicTransfer(sender, address(this), taxAmount);

                swapToTreasury(taxAmount);

            }

        }

        return amount;

    }

    function _transferFrom(

        address sender,

        address recipient,

        uint256 amount

    ) internal returns (bool) {

        require(!blacklist[sender] && !blacklist[recipient], "in_blacklist");

        checkLimit(sender, recipient, amount);

        amount = taxTransfer(sender, recipient, amount);

        if (inSwap) {

            return _basicTransfer(sender, recipient, amount);

        }

        if (shouldRebase()) {

           rebase();

        }



        if (shouldAddLiquidity()) {

            addLiquidity();

        }



        if (shouldSwapBack()) {

            swapBack();

        }



        uint256 gonAmount = amount.mul(_gonsPerFragment);

        _gonBalances[sender] = _gonBalances[sender].sub(gonAmount);

        uint256 gonAmountReceived = shouldTakeFee(sender, recipient)

            ? takeFee(sender, recipient, gonAmount)

            : gonAmount;

        _gonBalances[recipient] = _gonBalances[recipient].add(

            gonAmountReceived

        );



        if(!isDividendExempt[sender]){ try distributor.setShare(sender, balanceOf(sender)) {} catch {} }

        if(!isDividendExempt[recipient]){ try distributor.setShare(recipient, balanceOf(recipient)) {} catch {} }



        try distributor.process(distributorGas) {} catch {}



        emit Transfer(

            sender,

            recipient,

            gonAmountReceived.div(_gonsPerFragment)

        );

        return true;

    }



    function takeFee(

        address sender,

        address recipient,

        uint256 gonAmount

    ) internal  returns (uint256) {

        uint256 _totalFee = totalFee;

        uint256 _treasuryFee = treasuryFee;



        if (recipient == pair) {

            _totalFee = totalFee.add(sellFee);

            _treasuryFee = treasuryFee.add(sellFee);

        }



        uint256 feeAmount = gonAmount.div(feeDenominator).mul(_totalFee);



        _gonBalances[autofirePit] = _gonBalances[autofirePit].add(

            gonAmount.div(feeDenominator).mul(autofirePitFee)

        );

        _gonBalances[address(this)] = _gonBalances[address(this)].add(

            gonAmount.div(feeDenominator).mul(_treasuryFee.add(safuDividendFee))

        );

        _gonBalances[autoLiquidityReceiver] = _gonBalances[autoLiquidityReceiver].add(

            gonAmount.div(feeDenominator).mul(liquidityFee)

        );



        emit Transfer(sender, address(this), feeAmount.div(_gonsPerFragment));

        return gonAmount.sub(feeAmount);

    }



    function addLiquidity() internal swapping {

        uint256 autoLiquidityAmount = _gonBalances[autoLiquidityReceiver].div(

            _gonsPerFragment

        );

        _gonBalances[address(this)] = _gonBalances[address(this)].add(

            _gonBalances[autoLiquidityReceiver]

        );

        _gonBalances[autoLiquidityReceiver] = 0;

        uint256 amountToLiquify = autoLiquidityAmount.div(2);

        uint256 amountToSwap = autoLiquidityAmount.sub(amountToLiquify);



        if( amountToSwap == 0 ) {

            return;

        }

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = router.WETH();



        uint256 balanceBefore = address(this).balance;





        router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            amountToSwap,

            0,

            path,

            address(this),

            block.timestamp

        );



        uint256 amountETHLiquidity = address(this).balance.sub(balanceBefore);



        if (amountToLiquify > 0&&amountETHLiquidity > 0) {

            router.addLiquidityETH{value: amountETHLiquidity}(

                address(this),

                amountToLiquify,

                0,

                0,

                autoLiquidityReceiver,

                block.timestamp

            );

        }

        _lastAddLiquidityTime = block.timestamp;

    }

    function swapToTreasury(uint256 amount) internal swapping {

        uint256 balanceBefore = address(this).balance;

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = router.WETH();

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            amount,

            0,

            path,

            address(this),

            block.timestamp

        );

        uint256 amountETHToTreasuryAndSIF = address(this).balance.sub(

            balanceBefore

        );



        (bool success, ) = payable(treasuryReceiver).call{

            value: amountETHToTreasuryAndSIF,

            gas: 30000

        }("");

    }

    function swapBack() internal swapping {



        uint256 amountToSwap = _gonBalances[address(this)].div(_gonsPerFragment);



        if( amountToSwap == 0) {

            return;

        }



        uint256 balanceBefore = address(this).balance;

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = router.WETH();





        router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            amountToSwap,

            0,

            path,

            address(this),

            block.timestamp

        );



        uint256 amountETHToTreasuryAndSIF = address(this).balance.sub(

            balanceBefore

        );



        (bool success, ) = payable(treasuryReceiver).call{

            value: amountETHToTreasuryAndSIF.mul(treasuryFee).div(

                treasuryFee.add(safuDividendFee)

            ),

            gas: 30000

        }("");



        try distributor.deposit {

            value: amountETHToTreasuryAndSIF.mul(safuDividendFee).div(treasuryFee.add(safuDividendFee))

        } () {} catch {}        

    }



    function withdrawAllToTreasury() external swapping onlyOwner {



        uint256 amountToSwap = _gonBalances[address(this)].div(_gonsPerFragment);

        require( amountToSwap > 0,"There is no AlphaPro token deposited in token contract");

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = router.WETH();

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            amountToSwap,

            0,

            path,

            treasuryReceiver,

            block.timestamp

        );

    }



    function shouldTakeFee(address from, address to)

        internal

        view

        returns (bool)

    {

        return 

            (pair == from || pair == to) &&

            !_isFeeExempt[from];

    }



    function shouldRebase() internal view returns (bool) {

        return

            _autoRebase &&

            (_totalSupply < MAX_SUPPLY) &&

            msg.sender != pair  &&

            !inSwap &&

            block.timestamp >= (_lastRebasedTime + 30 minutes);

    }



    function shouldAddLiquidity() internal view returns (bool) {

        return

            _autoAddLiquidity && 

            !inSwap && 

            msg.sender != pair &&

            block.timestamp >= (_lastAddLiquidityTime + 2 days);

    }



    function shouldSwapBack() internal view returns (bool) {

        return 

            !inSwap &&

            msg.sender != pair  ; 

    }



    function setAutoRebase(bool _flag) external onlyOwner {

        if (_flag) {

            _autoRebase = _flag;

            _lastRebasedTime = block.timestamp;

        } else {

            _autoRebase = _flag;

        }

    }



    function setAutoAddLiquidity(bool _flag) external onlyOwner {

        if(_flag) {

            _autoAddLiquidity = _flag;

            _lastAddLiquidityTime = block.timestamp;

        } else {

            _autoAddLiquidity = _flag;

        }

    }



    function allowance(address owner_, address spender)

        external

        view

        override

        returns (uint256)

    {

        return _allowedFragments[owner_][spender];

    }



    function decreaseAllowance(address spender, uint256 subtractedValue)

        external

        returns (bool)

    {

        uint256 oldValue = _allowedFragments[msg.sender][spender];

        if (subtractedValue >= oldValue) {

            _allowedFragments[msg.sender][spender] = 0;

        } else {

            _allowedFragments[msg.sender][spender] = oldValue.sub(

                subtractedValue

            );

        }

        emit Approval(

            msg.sender,

            spender,

            _allowedFragments[msg.sender][spender]

        );

        return true;

    }



    function increaseAllowance(address spender, uint256 addedValue)

        external

        returns (bool)

    {

        _allowedFragments[msg.sender][spender] = _allowedFragments[msg.sender][

            spender

        ].add(addedValue);

        emit Approval(

            msg.sender,

            spender,

            _allowedFragments[msg.sender][spender]

        );

        return true;

    }



    function approve(address spender, uint256 value)

        external

        override

        returns (bool)

    {

        _allowedFragments[msg.sender][spender] = value;

        emit Approval(msg.sender, spender, value);

        return true;

    }



    function checkFeeExempt(address _addr) external view returns (bool) {

        return _isFeeExempt[_addr];

    }



    function setIsDividendExempt(address holder, bool exempt) external onlyOwner {

        require(holder != address(this) && holder != pair);

        isDividendExempt[holder] = exempt;



        if (exempt) {

            distributor.setShare(holder, 0);

        } else {

            distributor.setShare(holder, balanceOf(holder));

        }

    }



    function setDistributionCriteria(uint256 _minPeriod, uint256 _minDistribution) external onlyOwner {

        distributor.setDistributionCriteria(_minPeriod, _minDistribution);

    }



    function setDistributorSettings(uint256 gas) external onlyOwner {

        require(gas < 750000, "Gas must be lower than 750000");

        distributorGas = gas;

    }



    function getCirculatingSupply() public view returns (uint256) {

        return

            (TOTAL_GONS.sub(_gonBalances[DEAD]).sub(_gonBalances[ZERO])).div(

                _gonsPerFragment

            );

    }



    function isNotInSwap() external view returns (bool) {

        return !inSwap;

    }



    function manualSync() external {

        IPancakeSwapPair(pair).sync();

    }



    function setFeeReceivers(

        address _autoLiquidityReceiver,

        address _treasuryReceiver,

        address _autofirePit

    ) external onlyOwner {

        autoLiquidityReceiver = _autoLiquidityReceiver;

        treasuryReceiver = _treasuryReceiver;

        autofirePit = _autofirePit;      

    }

    function setTransferTax(uint256 newTransferTax) external onlyOwner {

        require(newTransferTax <= 5000, "AlphaPro: Maximum Transfer Tax Is 50%");

        require(newTransferTax >= 0, "AlphaPro: Minimum Transfer Tax Is 0%");

        transferTax = newTransferTax;

    }

    function setLimitSell(uint256 newMaxSellPerDay) external onlyOwner {

        require(newMaxSellPerDay >= 5000, "Alpha Protocol: Minimum To Set is 50%");

        require(newMaxSellPerDay <= 7000, "Alpha Protocol: Maximum to set is 70%");

        maxSellPerDay = newMaxSellPerDay;

    }



    function getLiquidityBacking(uint256 accuracy)

        public

        view

        returns (uint256)

    {

        uint256 liquidityBalance = _gonBalances[pair].div(_gonsPerFragment);

        return

            accuracy.mul(liquidityBalance.mul(2)).div(getCirculatingSupply());

    }



    function setWhitelist(address _addr) external onlyOwner {

        _isFeeExempt[_addr] = true;

    }



    function setBotBlacklist(address _botAddress, bool _flag) external onlyOwner {

        require(isContract(_botAddress), "only contract address, not allowed externally owned account");

        blacklist[_botAddress] = _flag;    

