        // Exclude system addresses from fee

        _isExcludedFromFee.add(owner());

        _isExcludedFromFee.add(address(this));



        _isExcludedFromSwapAndLiquify.add(uniswapV2Pair);



        emit Transfer(address(0), cOwner, _tTotal);

