        bLiquidityFee = liquidityFee;

        bMarketingFee = marketingFee;

        bDevFee = devFee;

        bJackpotFee = jackpotFee;



        emit BuyFeesChanged(bLiquidityFee, bMarketingFee, bDevFee, bJackpotFee);

