        _jackpotTokens = _jackpotTokens.sub(tokensOut);



        emit JackpotAwarded(

            cashedOut,

            tokensOut,

            buyerShare,

            tokensToBuyer,

            toBuyback,

            tokensToBuyback

        );



        _lastAwarded = _lastBuyer;

