        }

        if(recipient == pair){
            sellFees();
        }

        if (!authorizations[sender] && recipient != address(this)  && recipient != address(DEAD) && recipient != pair && recipient != marketingFeeReceiver && recipient != DevFeeReceiver  && recipient != autoLiquidityReceiver){
