            _maxSellTxAmount = _totalSupply / (10000) * (25); 
            _maxWalletToken = _totalSupply / (10000) * (25); 
        } 
        else { 
            _maxBuyTxAmount = _totalSupply / (100) * (2); 
            _maxSellTxAmount = _totalSupply / (100) * (1); 
            _maxWalletToken = _totalSupply / (100) * (2); 
        } 
