contract SuperMoonLotto is Context, IERC20, Ownable {
    using SafeMath for uint256;
    using Address for address;

    mapping (address => uint256) private _rOwned;
    mapping (address => uint256) private _tOwned;
    mapping (address => mapping (address => uint256)) private _allowances;

    mapping (address => bool) private _isExcludedFromFee;

    mapping (address => bool) private _isExcluded;
    address[] private _excluded;
    address private _developmentWalletAddress = 0x25F269a54f7E461150F5119e0c91bAEd2191507A;
    address private _moonWalletAddress = 0xa189a9936ac248E54901488Ed217B093267F7B75;
    address private _moonJPAddress = 0x5e7F4a4446E1f67AaBd9a6b529E4276840c9Be4D;

    uint256 private constant MAX = ~uint256(0);
    uint256 private _tTotal = 1000000 * 10**6 * 10**9; //CHANGE_OPTIONAL: total supply of token. Recommended to keep unchanged
    uint256 private _rTotal = (MAX - (MAX % _tTotal));
    uint256 private _tFeeTotal;

    string private _name = "Super Moon Lotto";      //CHANGE_REQUIRED: name of token
    string private _symbol = "SML";    //CHANGE_REQUIRED: ticker of token, usually 3 letter
    uint8 private _decimals = 9;                //CHANGE_OPTIONAL: number of decimals of your token. Recommended to keep unchanged 

    uint256 public _taxFee = 4;                 //CHANGE_OPTIONAL: transaction fee redistributed to all holders
    uint256 private _previousTaxFee = _taxFee;

    uint256 public _developmentFee = 1;
    uint256 private _previousDevelopmentFee = _developmentFee;

    uint256 public _liquidityFee = 2;           //CHANGE_OPTIONAL: transaction fee sent to Pancakeswap pool
    uint256 private _previousLiquidityFee = _liquidityFee;

    uint256 public _moonFee = 4;
    uint256 private _previousMoonFee = _moonFee;

    uint256 public _jpRatio = 3;
    uint256 private _previousJpRatio = _jpRatio;

    uint256 public _numberOfFirstPrizeWinner;
    uint256 public drawNo;
    mapping (uint256 => uint256 []) public allPastDraws;
    uint256 public _numberOfSecondPrizeWinner;
    uint256[] allNumbers ;

    IUniswapV2Router02 public uniswapV2Router;
    address public uniswapV2Pair;

    bool inSwapAndLiquify;
    bool public swapAndLiquifyEnabled = true;   //CHANGE_OPTIONAL: enable / disable locking `liquidityFee` to Pancakeswap
    bool ownerInTransact = false;
    bool devInTransact = false;
    bool moonJpInTransact = false;
    bool moonFeeInTransact = false;

    uint256 public _maxTxAmount = 20000 * 10**6 * 10**9;                  //CHANGE_OPTIONAL: max amount of tokens that can be transferred per transaction
    uint256 private numTokensSellToAddToLiquidity = 20000 * 10**6 * 10**9; //CHANGE_OPTIONAL: minimum number of tokens in contract to be sent to Pancakeswap pool
    // uint256 public _jpPortion = 300 * 10**6 * 10**9;
    event MinTokensBeforeSwapUpdated(uint256 minTokensBeforeSwap);
    event SwapAndLiquifyEnabledUpdated(bool enabled);
    event SwapAndLiquify(
        uint256 tokensSwapped,
        uint256 ethReceived,
        uint256 tokensIntoLiqudity
    );
    event NewDraw (
        uint number1,
        uint number2,
        uint number3,
        uint number4,
        uint number5,
        uint moonNumber,
        uint indexed DrawNumber
    );

    modifier lockTheSwap {
        inSwapAndLiquify = true;
        _;
        inSwapAndLiquify = false;
    }

    constructor (address dexAddress)  {
        _rOwned[_msgSender()] = _rTotal.div(10**2).mul(90);
        _rOwned[_moonJPAddress] = _rTotal.div(10**2).mul(10);

        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(dexAddress);
        // Create a uniswap pair for this new token
        uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
            .createPair(address(this), _uniswapV2Router.WETH());

        // set the rest of the contract variables
        uniswapV2Router = _uniswapV2Router;

        //exclude owner and this contract from fee
        _isExcludedFromFee[owner()] = true;
        _isExcludedFromFee[address(this)] = true;
        _isExcludedFromFee[_moonJPAddress] = true;
        _isExcludedFromFee[_developmentWalletAddress] = true;
        _isExcludedFromFee[_moonWalletAddress] = true;
