    address payable public marketingWalletAddress = payable(0xDBCA15b651c2a8E0BfBe2C3165F0262EB735243b);

    address payable public teamWalletAddress = payable(0xaA67797C2d66c6f5A88aD6a46C20208A9a76a356);

    address public immutable deadAddress = 0x000000000000000000000000000000000000dEaD;



    mapping (address => uint256) _balances;

    mapping (address => mapping (address => uint256)) private _allowances;



    mapping (address => bool) public isExcludedFromFee;

    mapping (address => bool) public isWalletLimitExempt;

    mapping (address => bool) public isTxLimitExempt;

    mapping (address => bool) public isMarketPair;



    uint256 public _buyLiquidityFee = 6;

    uint256 public _buyMarketingFee = 2;

    uint256 public _buyTeamFee = 2;



    uint256 public _sellLiquidityFee = 6;

    uint256 public _sellMarketingFee = 2;

    uint256 public _sellTeamFee = 2;



    uint256 public _liquidityShare = 4;

    uint256 public _marketingShare = 4;

    uint256 public _teamShare = 4;



    uint256 public _totalTaxIfBuying = 10;

    uint256 public _totalTaxIfSelling = 10;

    uint256 public _totalDistributionShares = 24;



    uint256 private _totalSupply =  1000000000 * 10**_decimals;

    uint256 public _maxTxAmount =   1000000000 * 10**_decimals;     

    uint256 public _walletMax =     1000000000 * 10**_decimals;      

    uint256 private minimumTokensBeforeSwap = 100 * 10**_decimals; 



    IUniswapV2Router02 public uniswapV2Router;

    address public uniswapPair;



