contract GoatWolf is ERC20, Ownable {

    uint256 public liquidityFee = 1;
    uint256 public projectFee = 5;

    uint256 totalFee = liquidityFee + projectFee;

    address payable private marketingWallet = payable(0x6F16B0Bc20bbBA9509a418D27fE0D0f6641e313B);
    address payable private developerWallet = payable(0xB1130EF5fb4805a090Fc3046d7Fe0cCf6c1c896E);
    address payable private charityWallet = payable(0x2726e2b53E963b7b91F9276fD329992939555d4f);

    bool public walletToWalletTransferWithoutFee = true;

    IUniswapV2Router02 public uniswapV2Router;
    address public  uniswapV2Pair;

    address private DEAD = 0x000000000000000000000000000000000000dEaD;

    uint256[3] public pCent= [45,45,10];

    bool private swapping;

    mapping (address => bool) private isExcludedFromFees;
    mapping (address => bool) public automatedMarketMakerPairs;

    constructor () ERC20("Goat Wolf", "GOATWOLF") 
    {   
        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
            .createPair(address(this), _uniswapV2Router.WETH());

        uniswapV2Router = _uniswapV2Router;

        _approve(address(this), address(uniswapV2Router), type(uint256).max);

        setAutomatedMarketMakerPair(uniswapV2Pair, true);

        isExcludedFromFees[owner()] = true;
        isExcludedFromFees[DEAD] = true;
        isExcludedFromFees[address(this)] = true;

        _mint(owner(), 1e9 * (10 ** 18));
    }

    function claimStuckTokens(address token) external onlyOwner {
        require(token != address(this), "Owner can not claim native tokens");
        if (token == address(0x0)) {
            payable(msg.sender).transfer(address(this).balance);
            return;
        }
        IERC20 ERC20token = IERC20(token);
        uint256 balance = ERC20token.balanceOf(address(this));
        ERC20token.transfer(msg.sender, balance);
    }

    function setAutomatedMarketMakerPair(address pair, bool value) private {
        require(automatedMarketMakerPairs[pair] != value, "This air is already set to that value");
        automatedMarketMakerPairs[pair] = value;
    }

    function excludeFromFees(address account) external onlyOwner {
        require(isExcludedFromFees[account] != true, "Account is already excluded");
        isExcludedFromFees[account] = true;
    }

    function isExcludedFromFeesFunction(address account) public view returns(bool) {
        return isExcludedFromFees[account];
    }

    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal  override {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        if(amount == 0) {
            super._transfer(from, to, 0);
            return;
        }

		uint256 contractTokenBalance = balanceOf(address(this));

        if( !swapping && contractTokenBalance > 0 && !automatedMarketMakerPairs[from]) 
        {
            swapping = true;

            uint256 liquidityTokens = (contractTokenBalance * liquidityFee) / totalFee;
            swapAndLiquidity(liquidityTokens);

            uint256 projectTokens = (contractTokenBalance * projectFee) / totalFee;
            swapAndSendMarketing(projectTokens);         

            swapping = false;
        }

        bool takeFee = !swapping;

        if(isExcludedFromFees[from] || isExcludedFromFees[to]) {
            takeFee = false;
        }
        if(walletToWalletTransferWithoutFee && from != uniswapV2Pair && to != uniswapV2Pair) {
            takeFee = false;
        }
        if(takeFee) {
        	uint256 fees = amount * totalFee / 100;

        	amount = amount - fees;

            super._transfer(from, address(this), fees);
        }
        super._transfer(from, to, amount);
    }

    function setFeeWallet(uint256 _liquidityFee, uint256 _projectFee) public onlyOwner 
    {
        require(_liquidityFee >= 1, "Liquidity Fee be more than 1.");
        require(_projectFee >= 5, "Project Fee be more than 5.");
        liquidityFee = _liquidityFee;
        projectFee = _projectFee;
    }

    function setPercentWallet(uint256[3] memory _pCent) public onlyOwner
    {
        pCent = _pCent;
    }

    function swapAndLiquidity(uint256 tokens) private {
        uint256 half = tokens / 2;
        uint256 otherHalf = tokens - half;

        uint256 initialBalance = address(this).balance;

        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            half,
            0, 
            path,
            address(this),
            block.timestamp);

        uint256 newBalance = address(this).balance - initialBalance;

        uniswapV2Router.addLiquidityETH{value: newBalance}(
            address(this),
            otherHalf,
            0, 
            0, 
            DEAD,
            block.timestamp
        );
    }

    function swapAndSendMarketing(uint256 tokenAmount) private {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0, 
            path,
            address(this),
            block.timestamp);
        sendBNB(address(this).balance);
    }

    function sendBNB(uint256 amount) private {
        developerWallet.transfer(amount * pCent[0] / 100);
        marketingWallet.transfer(amount * pCent[1] / 100);
        charityWallet.transfer(amount * pCent[2] / 100);
    }

    receive() external payable {
  	}
}

