        _marketMakerFee = marketMakerFeeNew;
        _marketingFee = marketingFeeNew;
        _lpFee = lpFeeNew;
        _stakeFee = stakeFeeNew;
        _totalTax = _marketMakerFee.add(_marketingFee).add(_lpFee).add(_stakeFee);
