  	function setWalletBalance(uint256 _maxWalletBalance) external onlyOwner{

  	    maxWalletBalance = _maxWalletBalance;

  	}



  	function setMaxBuyTransaction(uint256 _maxTxn) external onlyOwner {

  	    maxBuyTranscationAmount = _maxTxn * (10**18);

  	}



      function setMarketingFeeBuy(uint256 fee) external onlyOwner {

  	    _marketingFeeBuy = fee * (10**18);

    }



    function setBuybackFeeBuy(uint256 fee) external onlyOwner {

  	    _buybackFeeBuy = fee * (10**18);

    }



    function setLpFeeBuy(uint256 LpFeeBuy) external onlyOwner {

  	    _LpFeeBuy = LpFeeBuy * (10**18);

    }  



    function setMarketingFeeSell(uint256 fee) external onlyOwner {

