            _reflectionBalance[marketingAddress] = _reflectionBalance[marketingAddress].add(marketingFee.mul(rate));

            if(_isExcluded[marketingAddress]){

                _tokenBalance[marketingAddress] = _tokenBalance[marketingAddress].add(marketingFee);

            }



            emit Transfer(account,marketingAddress,marketingFee);

        }



        if(_liquidityFee != 0){

            uint256 liquidityFee = amount.mul(_liquidityFee).div(10**(_feeDecimal + 2));

            transferAmount = transferAmount.sub(liquidityFee);

            _reflectionBalance[address(this)] = _reflectionBalance[address(this)].add(liquidityFee.mul(rate));

            if(_isExcluded[address(this)]){

                _tokenBalance[address(this)] = _tokenBalance[address(this)].add(liquidityFee);

            }



            emit Transfer(account,address(this),liquidityFee);

        }





        if(_rewardFee != 0){

            uint256 rewardFee = amount.mul(_rewardFee).div(10**(_feeDecimal + 2));

            transferAmount = transferAmount.sub(rewardFee);

            _reflectionBalance[rewardAddress] = _reflectionBalance[rewardAddress].add(rewardFee.mul(rate));

            if(_isExcluded[rewardAddress]){

                _tokenBalance[rewardAddress] = _tokenBalance[rewardAddress].add(rewardFee);

            }



            emit Transfer(account,rewardAddress,rewardFee);

        }





        if(_ecosystemFee != 0){

            uint256 ecosystemFee = amount.mul(_ecosystemFee).div(10**(_feeDecimal + 2));

            transferAmount = transferAmount.sub(ecosystemFee);

            _reflectionBalance[ecosystemAddress] = _reflectionBalance[ecosystemAddress].add(ecosystemFee.mul(rate));

            if(_isExcluded[ecosystemAddress]){

                _tokenBalance[ecosystemAddress] = _tokenBalance[ecosystemAddress].add(ecosystemFee);

            }



            emit Transfer(account,ecosystemAddress,ecosystemFee);

        }





        return transferAmount;

    }





