        _isExcludedFromFees[DEAD] = true;

        _isExcludedFromFees[address(this)] = true;

    }



    receive() external payable {



  	}



    function claimStuckTokens(address token) external onlyOwner {

        require(token != address(this), "Owner cannot claim native tokens");

        if (token == address(0x0)) {

            payable(msg.sender).transfer(address(this).balance);

            return;

        }

        IERC20 ERC20token = IERC20(token);

        uint256 balance = ERC20token.balanceOf(address(this));

        ERC20token.transfer(msg.sender, balance);

    }



    //=======FeeManagement=======//

    function excludeFromFees(address account, bool excluded) external onlyOwner {

        require(_isExcludedFromFees[account] != excluded, "Account is already the value of 'excluded'");

        _isExcludedFromFees[account] = excluded;



        emit ExcludeFromFees(account, excluded);

    }



    function isExcludedFromFees(address account) public view returns(bool) {

        return _isExcludedFromFees[account];

    }



    function changeMarketingWallet(address _marketingWallet) external onlyOwner {

        require(_marketingWallet != marketingWallet, "Marketing wallet is already that address");

        require(_marketingWallet != address(0), "Marketing wallet cannot be the zero address");

        marketingWallet = _marketingWallet;

        emit MarketingWalletChanged(marketingWallet);

    }



    function changeCharityWallet(address _charityWallet) external onlyOwner {

        require(_charityWallet != charityWallet, "Charity wallet is already that address");

        require(_charityWallet != address(0), "Charity wallet cannot be the zero address");

        charityWallet = _charityWallet;

        emit CharityWalletChanged(charityWallet);

    }



    function _transfer(

        address from,

        address to,

        uint256 amount

    ) internal override {

        require(from != address(0), "ERC20: transfer from the zero address");

        require(to != address(0), "ERC20: transfer to the zero address");



        if(amount == 0) {

            super._transfer(from, to, 0);

            return;

        }



		uint256 contractTokenBalance = balanceOf(address(this));



        bool canSwap = contractTokenBalance >= swapTokensAtAmount;



        if( canSwap &&

            !swapping &&

            to == uniswapV2Pair

        ) {

            swapping = true;

            contractTokenBalance = swapTokensAtAmount;







            uint256 liquidityShare = liquidityFeeOnBuy + liquidityFeeOnSell;

            uint256 marketingShare = marketingFeeOnBuy + marketingFeeOnSell;

            uint256 rewardShare    = rewardFeeOnBuy    + rewardFeeOnSell;

            uint256 charityShare   = charityFeeOnBuy   + charityFeeOnSell;

            uint256 totalShare = liquidityShare + marketingShare + rewardShare + charityShare ;



            uint256 liquidityTokens;



            if(liquidityShare > 0) {

                liquidityTokens = contractTokenBalance * liquidityShare / totalShare;

                swapAndLiquify(liquidityTokens);

            }



            contractTokenBalance -= liquidityTokens;

            uint256 bnbShare = marketingShare + rewardShare + charityShare;



            if(contractTokenBalance > 0 && bnbShare > 0) {

                uint256 initialBalance = address(this).balance;



                address[] memory path = new address[](2);

                path[0] = address(this);

                path[1] = uniswapV2Router.WETH();



                uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

                    contractTokenBalance,

                    0,

                    path,

                    address(this),

                    block.timestamp);



                uint256 newBalance = address(this).balance - initialBalance;



                if(marketingShare > 0) {

                    uint256 marketingBNB = newBalance * marketingShare / bnbShare;

                    payable(marketingWallet).sendValue(marketingBNB);

                    emit SendMarketing(marketingBNB);

                }

                if(charityShare > 0){

                    uint256 charityBNB = newBalance * charityShare / bnbShare;

                    payable(charityWallet).sendValue(charityBNB);

                    emit SendCharity(charityBNB);

                }

                if(rewardShare > 0) {

                    uint256 rewardBNB = newBalance * rewardShare / bnbShare;

                    swapAndSendDividends(rewardBNB);

                }

            }



            swapping = false;

        }



        uint256 _totalFees;        

        uint256 burnTaxShare;



        if(((_isExcludedFromFees[from] || _isExcludedFromFees[to]) || (from != uniswapV2Pair && to != uniswapV2Pair)) || swapping) {

            _totalFees = 0;

        }else if(from == uniswapV2Pair) {

            _totalFees = _totalFeesOnBuy;

            burnTaxShare = autoBurnFeeOnBuy;

        } else {

            _totalFees = _totalFeesOnSell;

            burnTaxShare = autoBurnFeeOnSell;

        }

        if( _totalFees > 0) {

        	uint256 fees = (amount * _totalFees) / 100;

            amount -= fees;



            if (burnTaxShare > 0) {

                uint256 burnAmount = (fees * burnTaxShare) / _totalFees;

                fees -= burnAmount;

                super._transfer(from, DEAD, burnAmount);

        }

            super._transfer(from, address(this), fees);

        }





        if (maxWalletLimitEnabled) {

            if (_isExcludedFromMaxWalletLimit[from]  == false && 

                _isExcludedFromMaxWalletLimit[to]    == false &&

                to != uniswapV2Pair

            ) {

                uint balance  = balanceOf(to);

                require(

                    balance + amount <= maxWalletAmount, 

                    "MaxWallet: Recipient exceeds the maxWalletAmount"

                );

            }

        }



        super._transfer(from, to, amount);



        try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}

        try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}



        if(!swapping) {

	    	uint256 gas = gasForProcessing;



	    	try dividendTracker.process(gas) returns (uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {

	    		emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);

	    	}

	    	catch {



	    	}

        }

    }



//=======Swap=======//

    function swapAndLiquify(uint256 tokens) private {

        uint256 half = tokens / 2;

        uint256 otherHalf = tokens - half;



        uint256 initialBalance = address(this).balance;



        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();



        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            half,

            0, // accept any amount of ETH

            path,

            address(this),

            block.timestamp);



        uint256 newBalance = address(this).balance - initialBalance;



        uniswapV2Router.addLiquidityETH{value: newBalance}(

            address(this),

            otherHalf,

            0, // slippage is unavoidable

            0, // slippage is unavoidable

            DEAD,

            block.timestamp

        );



        emit SwapAndLiquify(half, newBalance, otherHalf);

    }



    function swapAndSendDividends(uint256 amount) private{

        address[] memory path = new address[](2);

        path[0] = uniswapV2Router.WETH();

        path[1] = rewardToken;



        uniswapV2Router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amount}(

            0,

            path,

            address(this),

            block.timestamp);



        uint256 balanceRewardToken = IERC20(rewardToken).balanceOf(address(this));

        bool success = IERC20(rewardToken).transfer(address(dividendTracker), balanceRewardToken);



        if (success) {

            dividendTracker.distributeDividends(balanceRewardToken);

            emit SendDividends(balanceRewardToken);

        }

    }



    function setSwapTokensAtAmount(uint256 newAmount) external onlyOwner{

        require(newAmount > totalSupply() / 100000, "SwapTokensAtAmount must be greater than 0.001% of total supply");

        swapTokensAtAmount = newAmount;

        emit SwapTokensAtAmountUpdated(newAmount);

    }



//=======MaxWallet=======//

    mapping(address => bool) private _isExcludedFromMaxWalletLimit;

    bool    public maxWalletLimitEnabled;

    uint256 public maxWalletAmount;



    function setEnableMaxWalletLimit(bool enable) external onlyOwner {

        require(

            enable != maxWalletLimitEnabled, 

            "Max wallet limit is already set to that state"

        );

        maxWalletLimitEnabled = enable;

        emit MaxWalletLimitStateChanged(maxWalletLimitEnabled);

    }



    function setMaxWalletAmount(uint256 _maxWalletAmount) external onlyOwner {



        require(_maxWalletAmount >= (totalSupply() / (10 ** decimals())) / 100 

                && _maxWalletAmount <= (totalSupply() / (10 ** decimals())) / 50, "Max wallet percentage can only be modified between 1% and 2% of total supply");



        maxWalletAmount = _maxWalletAmount * (10 ** decimals());

        emit MaxWalletLimitAmountChanged(maxWalletAmount);

    }



    function setExcludeFromMaxWallet(address account, bool exclude) external onlyOwner {

        require(

            _isExcludedFromMaxWalletLimit[account] != exclude, 

            "Account is already set to that state"

        );

        _isExcludedFromMaxWalletLimit[account] = exclude;

        emit ExcludedFromMaxWalletLimit(account, exclude);

    }



    function isExcludedFromMaxWalletLimit(address account) public view returns(bool) {

        return _isExcludedFromMaxWalletLimit[account];

    }



//=======Divivdend Tracker=======//

    function getClaimWait() external view returns(uint256) {

        return dividendTracker.claimWait();

    }



    function getTotalDividendsDistributed() external view returns (uint256) {

        return dividendTracker.totalDividendsDistributed();

    }



    function withdrawableDividendOf(address account) public view returns(uint256) {

    	return dividendTracker.withdrawableDividendOf(account);

  	}



	function dividendTokenBalanceOf(address account) public view returns (uint256) {

		return dividendTracker.balanceOf(account);

	}



    function totalRewardsEarned(address account) public view returns (uint256) {

        return dividendTracker.accumulativeDividendOf(account);

    }



	function excludeFromDividends(address account) external onlyOwner{

	    dividendTracker.excludeFromDividends(account);

	}



    function getAccountDividendsInfo(address account)

        external view returns (

            address,

            int256,

            int256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256) {

        return dividendTracker.getAccount(account);

    }



	function getAccountDividendsInfoAtIndex(uint256 index)

        external view returns (

            address,

            int256,

            int256,

            uint256,

            uint256,

            uint256,

            uint256,

            uint256) {

    	return dividendTracker.getAccountAtIndex(index);

    }



	function processDividendTracker(uint256 gas) external {

		(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) = dividendTracker.process(gas);

		emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, false, gas, tx.origin);

    }



    function claim() external {

		dividendTracker.processAccount(payable(msg.sender), false);

