        uint8 _treasury,

        uint8 _dev,

        uint8 _lp

    ) external onlyOwner {

        sellRates.rfi = _rfi;

        sellRates.treasury = _treasury;

        sellRates.dev = _dev;

        sellRates.lp = _lp;

        sellRates.toSwap = _treasury + _dev + _lp;

    }



    function setMaxTransactionAmount(

