    bool public public_mint_status = true;

    mapping(address => uint256) public publicMinted;

    constructor(string memory _initNotRevealedUri, string memory _contractURI) ERC721A("Guitarist", "Guitarist") {

    baseURI = "https://bafybeibwsk3xshtvcjaohx3jfdbl6oqnfiumy6mv4ocvcpyohlau22vz7e.ipfs.nftstorage.link/";
    setNotRevealedURI(_initNotRevealedUri);   
    setRoyaltyInfo(owner(),500);
