        return dividendTracker.getNumberOfTokenHolders();

    }



    function _transfer(address from, address to, uint256 amount) internal override 

    {

        require(from != address(0), "BEP20: transfer from the zero address");

        require(to != address(0), "BEP20: transfer to the zero address");



        if(from != owner() && to != owner()) {

            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");

        }





        if(amount == 0) {

            super._transfer(from, to, 0);

            return;

        }



        uint256 contractTokenBalance = balanceOf(address(this));



        bool canSwap = contractTokenBalance >= swapTokensAtAmount;



        if( canSwap && !swapping && swapAndLiquifyEnabled &&

        !automatedMarketMakerPairs[from] && from != owner()) 

        {

            swapping = true;



            checkForBuyBack();



            uint256 marketingTokens = contractTokenBalance.mul(marketingFee+developerFee).div(totalFees);

            swapAndSendToFee(marketingTokens);



            uint256 swapTokens = contractTokenBalance.mul(liquidityFee+buybackFee).div(totalFees);

            swapAndLiquify(swapTokens);



            uint256 sellTokens = balanceOf(address(this));

            swapAndSendDividends(sellTokens);



            swapping = false;

        }



        bool takeFee = !swapping;



        // if any account belongs to _isExcludedFromFee account then remove the fee

        if(_isExcludedFromFees[from] || _isExcludedFromFees[to]) {

            takeFee = false;

        }



        if(takeFee) {

            uint256 fees = amount.mul(totalFees).div(100);

            // if(automatedMarketMakerPairs[to]){

            //     fees += amount.mul(1).div(100);

            // }

            amount = amount.sub(fees);



            super._transfer(from, address(this), fees);

        }



        checkForWhale(amount, from, to);

        super._transfer(from, to, amount);



        try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}

        try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}



        if(!swapping) {

            uint256 gas = gasForProcessing;



            try dividendTracker.process(gas) returns (uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {

                emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);

            }

            catch {



            }

        }

    }



    function swapAndSendToFee(uint256 tokens) private  

    {

        uint256 initialBUSDBalance = IBEP20(BUSD).balanceOf(address(this));

        swapTokensForBUSD(tokens);

        uint256 newBalance = (IBEP20(BUSD).balanceOf(address(this))).sub(initialBUSDBalance);



        uint256 marketingShare = newBalance.div(marketingFee+developerFee).mul(marketingFee);

        IBEP20(BUSD).transfer(_marketingWalletAddress, marketingShare);

        IBEP20(BUSD).transfer(_developerWalletAddress, newBalance.sub(marketingShare));

    }



    function swapAndLiquify(uint256 tokens) private 

    {

       uint256 swapableFee = liquidityFee.add(buybackFee);

        uint256 halfLiquidityTokens = tokens.div(swapableFee).mul(liquidityFee).div(2);

        uint256 swapableTokens = tokens.sub(halfLiquidityTokens);



        uint256 initialBalance = address(this).balance;



        swapTokensForEth(swapableTokens); // <- this breaks the ETH -> HATE swap when swap+liquify is triggered



        // how much ETH did we just swap into?

        uint256 newBalance = address(this).balance.sub(initialBalance);

        uint256 bnbForLiquidity = newBalance.div(swapableFee).mul(liquidityFee).div(2);

        // add liquidity to uniswap

        addLiquidity(halfLiquidityTokens, bnbForLiquidity);

        emit SwapAndLiquify(halfLiquidityTokens, bnbForLiquidity, halfLiquidityTokens);

        //remaining bnb left for buyback purpose. 

    }





    function swapTokensForEth(uint256 tokenAmount) private {





        // generate the uniswap pair path of token -> weth

        address[] memory path = new address[](2);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();



        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // make the swap

        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(

            tokenAmount,

            0, // accept any amount of ETH

            path,

            address(this),

            block.timestamp

        );



    }



    function swapTokensForBUSD(uint256 tokenAmount) private {



        address[] memory path = new address[](3);

        path[0] = address(this);

        path[1] = uniswapV2Router.WETH();

        path[2] = BUSD;



        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // make the swap

        uniswapV2Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(

            tokenAmount,

            0,

            path,

            address(this),

            block.timestamp

        );

    }



    function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {



        // approve token transfer to cover all possible scenarios

        _approve(address(this), address(uniswapV2Router), tokenAmount);



        // add the liquidity

        uniswapV2Router.addLiquidityETH{value: ethAmount}(

            address(this),

            tokenAmount,

            0, // slippage is unavoidable

            0, // slippage is unavoidable

            address(0),

            block.timestamp

        );



    }



    function swapAndSendDividends(uint256 tokens) private{

        swapTokensForBUSD(tokens);

        uint256 dividends = IBEP20(BUSD).balanceOf(address(this));

        bool success = IBEP20(BUSD).transfer(address(dividendTracker), dividends);



        if (success) {

            dividendTracker.distributeBUSDDividends(dividends);

            emit SendDividends(tokens, dividends);

        }

    }



    function setMaxTxAmount(uint256 _amount) external onlyOwner

    {

        _maxTxAmount = _amount;

    }



    //----SWAP AND LIQUIFY---///

    bool public swapAndLiquifyEnabled = false;

