    bool private inSwap = false;
    bool private swapEnabled = true;

    uint256 public _maxTxAmount =  1 * (_tTotal/100);
    uint256 public _maxWalletSize = 1 * (_tTotal/100);
    uint256 public _swapTokensAtAmount = 20 *(_tTotal/1000);

