        address[] memory path = new address[](2);

        path[0] = WBNB;

        path[1] = address(this);



        Router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amount}(

            0,

            path,

            to,

            block.timestamp

        );



        _totalSupply = _totalSupply.sub(AutoBuyBackAmount);

        AllTimeBurned = AllTimeBurned + AutoBuyBackAmount;



